fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    
    // Handle the case where the array has only one element
    if n == 1 {
        return a.clone();
    }
    
    // Create a new vector with the same capacity
    let mut result = Vec::with_capacity(n);
    
    // First element of result is the last element of input
    result.push(a[n - 1]);
    
    // Copy all interior elements (indices 1 to n-2)
    for i in 1..n-1 {
        result.push(a[i]);
    }
    
    // Last element of result is the first element of input
    result.push(a[0]);
    
    result
}